import { type NextRequest } from 'next/server'
import { cookies } from 'next/headers'
import { isRelativeUrl } from '@/lib/utils/is-relative-url'
import { CodeChallengeMethod, OAuth2Client, generateCodeVerifier, generateState } from 'arctic'

export async function POST(req: NextRequest): Promise<Response> {
  const client = new OAuth2Client(
    process.env.NEXT_PUBLIC_VERCEL_CLIENT_ID ?? '',
    process.env.VERCEL_CLIENT_SECRET ?? '',
    `${req.nextUrl.origin}/api/auth/callback/vercel`,
  )

  const state = generateState()
  const verifier = generateCodeVerifier()
  const url = client.createAuthorizationURLWithPKCE(
    'https://vercel.com/oauth/authorize',
    state,
    CodeChallengeMethod.S256,
    verifier,
    [], // Vercel uses default scopes
  )

  const store = await cookies()
  const redirectTo = isRelativeUrl(req.nextUrl.searchParams.get('next') ?? '/')
    ? (req.nextUrl.searchParams.get('next') ?? '/')
    : '/'

  for (const [key, value] of [
    [`vercel_oauth_redirect_to`, redirectTo],
    [`vercel_oauth_state`, state],
    [`vercel_oauth_code_verifier`, verifier],
  ]) {
    store.set(key, value, {
      path: '/',
      secure: process.env.NODE_ENV === 'production',
      httpOnly: true,
      maxAge: 60 * 10,
      sameSite: 'lax',
    })
  }

  return Response.json({ url })
}

import { type NextRequest } from 'next/server'
import { OAuth2Client, type OAuth2Tokens } from 'arctic'
import { createSession, saveSession } from '@/lib/session/create'
import { cookies } from 'next/headers'

export async function GET(req: NextRequest): Promise<Response> {
  const code = req.nextUrl.searchParams.get('code')
  const state = req.nextUrl.searchParams.get('state')
  const cookieStore = await cookies()
  const storedState = cookieStore.get(`vercel_oauth_state`)?.value ?? null
  const storedVerifier = cookieStore.get(`vercel_oauth_code_verifier`)?.value ?? null
  const storedRedirectTo = cookieStore.get(`vercel_oauth_redirect_to`)?.value ?? null

  if (
    code === null ||
    state === null ||
    storedState !== state ||
    storedRedirectTo === null ||
    storedVerifier === null
  ) {
    return new Response(null, {
      status: 400,
    })
  }

  const client = new OAuth2Client(
    process.env.NEXT_PUBLIC_VERCEL_CLIENT_ID ?? '',
    process.env.VERCEL_CLIENT_SECRET ?? '',
    `${req.nextUrl.origin}/api/auth/callback/vercel`,
  )

  let tokens: OAuth2Tokens

  try {
    tokens = await client.validateAuthorizationCode('https://vercel.com/api/login/oauth/token', code, storedVerifier)
  } catch (error) {
    console.error('Failed to validate authorization code:', error)
    return new Response(null, {
      status: 400,
    })
  }

  const response = new Response(null, {
    status: 302,
    headers: {
      Location: storedRedirectTo,
    },
  })

  const session = await createSession({
    accessToken: tokens.accessToken(),
    expiresAt: tokens.accessTokenExpiresAt().getTime(),
    refreshToken: tokens.hasRefreshToken() ? tokens.refreshToken() : undefined,
  })

  if (!session) {
    console.error('[Vercel Callback] Failed to create session')
    return new Response('Failed to create session', { status: 500 })
  }

  // Note: Vercel tokens are already stored in users table by upsertUser() in createSession()

  await saveSession(response, session)

  cookieStore.delete(`vercel_oauth_state`)
  cookieStore.delete(`vercel_oauth_code_verifier`)
  cookieStore.delete(`vercel_oauth_redirect_to`)

  return response
}

import { NextResponse } from 'next/server'
import { getServerSession } from '@/lib/session/get-server-session'
import { checkRateLimit } from '@/lib/utils/rate-limit'

export async function GET() {
  try {
    const session = await getServerSession()
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const rateLimit = await checkRateLimit(session.user.id)

    return NextResponse.json({
      allowed: rateLimit.allowed,
      remaining: rateLimit.remaining,
      used: rateLimit.total - rateLimit.remaining,
      total: rateLimit.total,
      resetAt: rateLimit.resetAt.toISOString(),
    })
  } catch (error) {
    console.error('Error fetching rate limit:', error)
    return NextResponse.json({ error: 'Failed to fetch rate limit' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import type { Session, SessionUserInfo, Tokens } from '@/lib/session/types'
import { createSession, saveSession } from '@/lib/session/create'
import { saveSession as saveGitHubSession } from '@/lib/session/create-github'
import { getSessionFromReq } from '@/lib/session/server'
import { getOAuthToken } from '@/lib/session/get-oauth-token'

export async function GET(req: NextRequest) {
  const existingSession = await getSessionFromReq(req)

  // For GitHub users, just return the existing session without recreating it
  // For Vercel users, recreate the session to refresh user data
  let session: Session | undefined
  if (existingSession && existingSession.authProvider === 'github') {
    session = existingSession
  } else if (existingSession) {
    // Fetch Vercel token from database to recreate session
    const tokenData = await getOAuthToken(existingSession.user.id, 'vercel')
    if (tokenData) {
      const tokens: Tokens = {
        accessToken: tokenData.accessToken,
        expiresAt: tokenData.expiresAt?.getTime(),
      }
      session = await createSession(tokens)
    } else {
      session = existingSession
    }
  } else {
    session = undefined
  }

  const response = new Response(JSON.stringify(await getData(session)), {
    headers: { 'Content-Type': 'application/json' },
  })

  // Use the appropriate saveSession function based on auth provider
  if (session && session.authProvider === 'github') {
    await saveGitHubSession(response, session)
  } else {
    await saveSession(response, session)
  }

  return response
}

async function getData(session: Session | undefined): Promise<SessionUserInfo> {
  if (!session) {
    return { user: undefined }
  } else {
    return { user: session.user, authProvider: session.authProvider }
  }
}

import type { NextRequest } from 'next/server'
import { getSessionFromReq } from '@/lib/session/server'
import { isRelativeUrl } from '@/lib/utils/is-relative-url'
import { saveSession } from '@/lib/session/create'
import { getOAuthToken } from '@/lib/session/get-oauth-token'

export async function GET(req: NextRequest) {
  const session = await getSessionFromReq(req)
  if (session) {
    // Check which provider the user authenticated with
    if (session.authProvider === 'github') {
      // Revoke GitHub token - fetch from database
      try {
        const tokenData = await getOAuthToken(session.user.id, 'github')
        if (tokenData) {
          await fetch(`https://api.github.com/applications/${process.env.NEXT_PUBLIC_GITHUB_CLIENT_ID}/token`, {
            method: 'DELETE',
            headers: {
              Authorization: `Basic ${Buffer.from(`${process.env.NEXT_PUBLIC_GITHUB_CLIENT_ID}:${process.env.GITHUB_CLIENT_SECRET}`).toString('base64')}`,
              Accept: 'application/vnd.github.v3+json',
            },
            body: JSON.stringify({ access_token: tokenData.accessToken }),
          })
        }
      } catch (error) {
        console.error('Failed to revoke GitHub token:', error)
      }
    } else {
      // Revoke Vercel token - fetch from database
      try {
        const tokenData = await getOAuthToken(session.user.id, 'vercel')
        if (tokenData) {
          await fetch('https://vercel.com/api/login/oauth/token/revoke', {
            method: 'POST',
            body: new URLSearchParams({ token: tokenData.accessToken }),
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded',
              Authorization: `Basic ${Buffer.from(`${process.env.NEXT_PUBLIC_VERCEL_CLIENT_ID}:${process.env.VERCEL_CLIENT_SECRET}`).toString('base64')}`,
            },
          })
        }
      } catch (error) {
        console.error('Failed to revoke Vercel token:', error)
      }
    }
  }

  const response = Response.json({
    url: isRelativeUrl(req.nextUrl.searchParams.get('next') ?? '/') ? req.nextUrl.searchParams.get('next') : '/',
  })

  await saveSession(response, undefined)
  return response
}

import { type NextRequest } from 'next/server'
import { getSessionFromReq } from '@/lib/session/server'
import { db } from '@/lib/db/client'
import { accounts } from '@/lib/db/schema'
import { eq, and } from 'drizzle-orm'

export async function POST(req: NextRequest) {
  const session = await getSessionFromReq(req)

  if (!session?.user) {
    console.log('Disconnect GitHub: No session found')
    return Response.json({ error: 'Not authenticated' }, { status: 401 })
  }

  if (!session.user.id) {
    console.error('Session user.id is undefined. Session:', session)
    return Response.json({ error: 'Invalid session - user ID missing' }, { status: 400 })
  }

  // Can only disconnect if user didn't sign in with GitHub
  if (session.authProvider === 'github') {
    return Response.json({ error: 'Cannot disconnect primary authentication method' }, { status: 400 })
  }

  console.log('Disconnecting GitHub account for user:', session.user.id)

  try {
    await db.delete(accounts).where(and(eq(accounts.userId, session.user.id), eq(accounts.provider, 'github')))

    console.log('GitHub account disconnected successfully for user:', session.user.id)
    return Response.json({ success: true })
  } catch (error) {
    console.error('Error disconnecting GitHub:', error)
    return Response.json(
      { error: 'Failed to disconnect', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 },
    )
  }
}

import { type NextRequest } from 'next/server'
import { getSessionFromReq } from '@/lib/session/server'
import { db } from '@/lib/db/client'
import { users, accounts } from '@/lib/db/schema'
import { eq, and } from 'drizzle-orm'

export async function GET(req: NextRequest) {
  const session = await getSessionFromReq(req)

  if (!session?.user) {
    return Response.json({ connected: false })
  }

  if (!session.user.id) {
    console.error('GitHub status check: session.user.id is undefined')
    return Response.json({ connected: false })
  }

  try {
    // Check if user has GitHub as connected account
    const account = await db
      .select({
        username: accounts.username,
        createdAt: accounts.createdAt,
      })
      .from(accounts)
      .where(and(eq(accounts.userId, session.user.id), eq(accounts.provider, 'github')))
      .limit(1)

    if (account.length > 0) {
      return Response.json({
        connected: true,
        username: account[0].username,
        connectedAt: account[0].createdAt,
      })
    }

    // Check if user signed in with GitHub (primary account)
    const user = await db
      .select({
        username: users.username,
        createdAt: users.createdAt,
      })
      .from(users)
      .where(and(eq(users.id, session.user.id), eq(users.provider, 'github')))
      .limit(1)

    if (user.length > 0) {
      return Response.json({
        connected: true,
        username: user[0].username,
        connectedAt: user[0].createdAt,
      })
    }

    return Response.json({ connected: false })
  } catch (error) {
    console.error('Error checking GitHub connection status:', error)
    return Response.json({ connected: false, error: 'Failed to check status' }, { status: 500 })
  }
}

import { type NextRequest } from 'next/server'
import { cookies } from 'next/headers'
import { generateState } from 'arctic'
import { isRelativeUrl } from '@/lib/utils/is-relative-url'
import { getSessionFromReq } from '@/lib/session/server'

export async function GET(req: NextRequest): Promise<Response> {
  // Check if user is already authenticated with Vercel
  const session = await getSessionFromReq(req)

  const clientId = process.env.NEXT_PUBLIC_GITHUB_CLIENT_ID
  const redirectUri = `${req.nextUrl.origin}/api/auth/github/callback`

  if (!clientId) {
    return Response.redirect(new URL('/?error=github_not_configured', req.url))
  }

  const state = generateState()
  const store = await cookies()
  let redirectTo = isRelativeUrl(req.nextUrl.searchParams.get('next') ?? '/')
    ? (req.nextUrl.searchParams.get('next') ?? '/')
    : '/'

  // If user is already authenticated with Vercel, treat this as a "Connect GitHub" flow
  // Otherwise, treat it as a "Sign in with GitHub" flow
  const isSignInFlow = !session?.user
  const authMode = isSignInFlow ? 'signin' : 'connect'

  // Add a query parameter to show a toast message after redirect
  if (!isSignInFlow) {
    const redirectUrl = new URL(redirectTo, req.nextUrl.origin)
    redirectUrl.searchParams.set('github_connected', 'true')
    redirectTo = redirectUrl.pathname + redirectUrl.search
  }

  // Store state and redirect URL
  const cookiesToSet: [string, string][] = [
    [`github_auth_redirect_to`, redirectTo],
    [`github_auth_state`, state],
    [`github_auth_mode`, authMode],
  ]

  // If connecting (user already signed in), store their user ID
  if (!isSignInFlow && session?.user?.id) {
    cookiesToSet.push([`github_oauth_user_id`, session.user.id])
  }

  for (const [key, value] of cookiesToSet) {
    store.set(key, value, {
      path: '/',
      secure: process.env.NODE_ENV === 'production',
      httpOnly: true,
      maxAge: 60 * 10, // 10 minutes
      sameSite: 'lax',
    })
  }

  // Build GitHub authorization URL
  const params = new URLSearchParams({
    client_id: clientId,
    redirect_uri: redirectUri,
    scope: 'repo,read:user,user:email',
    state: state,
  })

  const url = `https://github.com/login/oauth/authorize?${params.toString()}`

  // Redirect directly to GitHub
  return Response.redirect(url)
}

import { type NextRequest } from 'next/server'
import { cookies } from 'next/headers'
import { db } from '@/lib/db/client'
import { users, accounts, tasks, connectors, keys } from '@/lib/db/schema'
import { eq, and } from 'drizzle-orm'
import { nanoid } from 'nanoid'
import { createGitHubSession, saveSession } from '@/lib/session/create-github'
import { encrypt } from '@/lib/crypto'

export async function GET(req: NextRequest): Promise<Response> {
  const code = req.nextUrl.searchParams.get('code')
  const state = req.nextUrl.searchParams.get('state')
  const cookieStore = await cookies()

  // Check if this is a sign-in flow or connect flow
  const authMode = cookieStore.get(`github_auth_mode`)?.value ?? null
  const isSignInFlow = authMode === 'signin'
  const isConnectFlow = authMode === 'connect'

  // Try both cookie patterns (new unified flow vs legacy oauth flow)
  const storedState = cookieStore.get(authMode ? `github_auth_state` : `github_oauth_state`)?.value ?? null
  const storedRedirectTo =
    cookieStore.get(authMode ? `github_auth_redirect_to` : `github_oauth_redirect_to`)?.value ?? null
  const storedUserId = cookieStore.get(`github_oauth_user_id`)?.value ?? null // Required for connect flow

  // For sign-in flow, we don't need storedUserId
  if (isSignInFlow) {
    if (code === null || state === null || storedState !== state || storedRedirectTo === null) {
      return new Response('Invalid OAuth state', {
        status: 400,
      })
    }
  } else {
    // For connect flow (including legacy oauth flow), we need storedUserId
    if (
      code === null ||
      state === null ||
      storedState !== state ||
      storedRedirectTo === null ||
      storedUserId === null
    ) {
      return new Response('Invalid OAuth state', {
        status: 400,
      })
    }
  }

  const clientId = process.env.NEXT_PUBLIC_GITHUB_CLIENT_ID
  const clientSecret = process.env.GITHUB_CLIENT_SECRET

  if (!clientId || !clientSecret) {
    return new Response('GitHub OAuth not configured', {
      status: 500,
    })
  }

  try {
    console.log('[GitHub Callback] Starting OAuth flow, mode:', authMode)

    // Exchange code for access token
    const tokenResponse = await fetch('https://github.com/login/oauth/access_token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify({
        client_id: clientId,
        client_secret: clientSecret,
        code: code,
      }),
    })

    if (!tokenResponse.ok) {
      console.error('[GitHub Callback] Token exchange failed with status:', tokenResponse.status)
      const errorText = await tokenResponse.text()
      console.error('[GitHub Callback] Error response:', errorText)
      return new Response('Failed to exchange code for token', { status: 400 })
    }

    const tokenData = (await tokenResponse.json()) as {
      access_token: string
      scope: string
      token_type: string
      error?: string
      error_description?: string
    }

    console.log('[GitHub Callback] Token data received, has access_token:', !!tokenData.access_token)

    if (!tokenData.access_token) {
      console.error('[GitHub Callback] Failed to get GitHub access token:', tokenData)
      return new Response(
        `Failed to authenticate with GitHub: ${tokenData.error_description || tokenData.error || 'Unknown error'}`,
        { status: 400 },
      )
    }

    // Fetch GitHub user info
    const userResponse = await fetch('https://api.github.com/user', {
      headers: {
        Authorization: `Bearer ${tokenData.access_token}`,
        Accept: 'application/vnd.github.v3+json',
      },
    })

    const githubUser = (await userResponse.json()) as {
      login: string
      id: number
    }

    if (isSignInFlow) {
      // SIGN-IN FLOW: Create a new session for the GitHub user
      console.log('[GitHub Callback] Sign-in flow - creating GitHub session')
      const session = await createGitHubSession(tokenData.access_token, tokenData.scope)

      if (!session) {
        console.error('[GitHub Callback] Failed to create GitHub session')
        return new Response('Failed to create session', { status: 500 })
      }

      console.log('[GitHub Callback] GitHub session created for user:', session.user.id)
      // Note: Tokens are already stored in users table by upsertUser() in createGitHubSession()

      // Create response with redirect
      const response = new Response(null, {
        status: 302,
        headers: {
          Location: storedRedirectTo,
        },
      })

      // Save session to cookie
      await saveSession(response, session)

      // Clean up cookies
      cookieStore.delete(`github_auth_state`)
      cookieStore.delete(`github_auth_redirect_to`)
      cookieStore.delete(`github_auth_mode`)

      return response
    } else {
      // CONNECT FLOW: Add GitHub account to existing Vercel user
      // Encrypt the access token before storing
      const encryptedToken = encrypt(tokenData.access_token)

      // Check if this GitHub account is already connected somewhere
      const existingAccount = await db
        .select()
        .from(accounts)
        .where(and(eq(accounts.provider, 'github'), eq(accounts.externalUserId, `${githubUser.id}`)))
        .limit(1)

      if (existingAccount.length > 0) {
        const connectedUserId = existingAccount[0].userId

        // If the GitHub account belongs to a different user, we need to merge accounts
        if (connectedUserId !== storedUserId) {
          console.log(
            `[GitHub Callback] Merging accounts: GitHub account ${githubUser.id} belongs to user ${connectedUserId}, connecting to user ${storedUserId}`,
          )

          // Transfer all tasks, connectors, accounts, and keys from old user to new user
          await db.update(tasks).set({ userId: storedUserId! }).where(eq(tasks.userId, connectedUserId))
          await db.update(connectors).set({ userId: storedUserId! }).where(eq(connectors.userId, connectedUserId))
          await db.update(accounts).set({ userId: storedUserId! }).where(eq(accounts.userId, connectedUserId))
          await db.update(keys).set({ userId: storedUserId! }).where(eq(keys.userId, connectedUserId))

          // Delete the old user record (this will cascade delete their accounts/keys)
          await db.delete(users).where(eq(users.id, connectedUserId))

          console.log(
            `[GitHub Callback] Account merge complete. Old user ${connectedUserId} merged into ${storedUserId}`,
          )

          // Update the GitHub account token
          await db
            .update(accounts)
            .set({
              userId: storedUserId!,
              accessToken: encryptedToken,
              scope: tokenData.scope,
              username: githubUser.login,
              updatedAt: new Date(),
            })
            .where(eq(accounts.id, existingAccount[0].id))
        } else {
          // Same user, just update the token
          await db
            .update(accounts)
            .set({
              accessToken: encryptedToken,
              scope: tokenData.scope,
              username: githubUser.login,
              updatedAt: new Date(),
            })
            .where(eq(accounts.id, existingAccount[0].id))
        }
      } else {
        // No existing GitHub account connection, create a new one
        await db.insert(accounts).values({
          id: nanoid(),
          userId: storedUserId!,
          provider: 'github',
          externalUserId: `${githubUser.id}`, // Store GitHub numeric ID
          accessToken: encryptedToken,
          scope: tokenData.scope,
          username: githubUser.login,
        })
      }

      // Clean up cookies (handle both new and legacy cookie names)
      if (authMode) {
        cookieStore.delete(`github_auth_state`)
        cookieStore.delete(`github_auth_redirect_to`)
        cookieStore.delete(`github_auth_mode`)
      } else {
        cookieStore.delete(`github_oauth_state`)
        cookieStore.delete(`github_oauth_redirect_to`)
      }
      cookieStore.delete(`github_oauth_user_id`)

      // Redirect back to app
      return Response.redirect(new URL(storedRedirectTo, req.nextUrl.origin))
    }
  } catch (error) {
    console.error('[GitHub Callback] OAuth callback error:', error)
    console.error('[GitHub Callback] Error stack:', error instanceof Error ? error.stack : 'No stack trace')
    return new Response(
      `Failed to complete GitHub authentication: ${error instanceof Error ? error.message : 'Unknown error'}`,
      { status: 500 },
    )
  }
}

