import 'server-only'

import { db } from '@/lib/db/client'
import { users, accounts } from '@/lib/db/schema'
import { eq, and } from 'drizzle-orm'
import { decrypt } from '@/lib/crypto'

type OAuthProvider = 'github' | 'vercel'

/**
 * Get the OAuth access token for a user from the database
 * Returns the decrypted token or null if not found
 *
 * For GitHub: Checks accounts table first (connected account), then users table (primary account)
 * For Vercel: Gets from users table (primary account only)
 */
export async function getOAuthToken(
  userId: string,
  provider: OAuthProvider,
): Promise<{ accessToken: string; refreshToken: string | null; expiresAt: Date | null } | null> {
  try {
    if (provider === 'github') {
      // Check if user has GitHub as a connected account
      const account = await db
        .select({
          accessToken: accounts.accessToken,
          refreshToken: accounts.refreshToken,
          expiresAt: accounts.expiresAt,
        })
        .from(accounts)
        .where(and(eq(accounts.userId, userId), eq(accounts.provider, 'github')))
        .limit(1)

      if (account[0]?.accessToken) {
        return {
          accessToken: decrypt(account[0].accessToken),
          refreshToken: account[0].refreshToken ? decrypt(account[0].refreshToken) : null,
          expiresAt: account[0].expiresAt,
        }
      }

      // Fall back to checking if user signed in with GitHub (primary account)
      const user = await db
        .select({
          accessToken: users.accessToken,
          refreshToken: users.refreshToken,
        })
        .from(users)
        .where(and(eq(users.id, userId), eq(users.provider, 'github')))
        .limit(1)

      if (user[0]?.accessToken) {
        return {
          accessToken: decrypt(user[0].accessToken),
          refreshToken: user[0].refreshToken ? decrypt(user[0].refreshToken) : null,
          expiresAt: null, // Users table doesn't have expiresAt
        }
      }
    } else if (provider === 'vercel') {
      // Vercel is only available as a primary account
      const user = await db
        .select({
          accessToken: users.accessToken,
          refreshToken: users.refreshToken,
        })
        .from(users)
        .where(and(eq(users.id, userId), eq(users.provider, 'vercel')))
        .limit(1)

      if (user[0]?.accessToken) {
        return {
          accessToken: decrypt(user[0].accessToken),
          refreshToken: user[0].refreshToken ? decrypt(user[0].refreshToken) : null,
          expiresAt: null, // Users table doesn't have expiresAt
        }
      }
    }

    return null
  } catch (error) {
    console.error('Error fetching OAuth token:', error)
    return null
  }
}

'use client'

import { useEffect } from 'react'
import { useSetAtom } from 'jotai'
import { sessionAtom, sessionInitializedAtom } from '@/lib/atoms/session'
import { githubConnectionAtom, githubConnectionInitializedAtom } from '@/lib/atoms/github-connection'
import type { SessionUserInfo } from '@/lib/session/types'
import type { GitHubConnection } from '@/lib/atoms/github-connection'

export function SessionProvider() {
  const setSession = useSetAtom(sessionAtom)
  const setInitialized = useSetAtom(sessionInitializedAtom)
  const setGitHubConnection = useSetAtom(githubConnectionAtom)
  const setGitHubInitialized = useSetAtom(githubConnectionInitializedAtom)

  useEffect(() => {
    const fetchSession = async () => {
      try {
        const response = await fetch('/api/auth/info')
        const data: SessionUserInfo = await response.json()
        setSession(data)
        setInitialized(true)
      } catch (error) {
        console.error('Failed to fetch session:', error)
        setSession({ user: undefined })
        setInitialized(true)
      }
    }

    const fetchGitHubConnection = async () => {
      try {
        const response = await fetch('/api/auth/github/status')
        const data: GitHubConnection = await response.json()
        setGitHubConnection(data)
        setGitHubInitialized(true)
      } catch (error) {
        console.error('Failed to fetch GitHub connection:', error)
        setGitHubConnection({ connected: false })
        setGitHubInitialized(true)
      }
    }

    const fetchAll = async () => {
      await Promise.all([fetchSession(), fetchGitHubConnection()])
    }

    fetchAll()

    // Refresh both every minute
    const interval = setInterval(fetchAll, 60000)

    // Refresh on focus
    const handleFocus = () => fetchAll()
    window.addEventListener('focus', handleFocus)

    return () => {
      clearInterval(interval)
      window.removeEventListener('focus', handleFocus)
    }
  }, [setSession, setInitialized, setGitHubConnection, setGitHubInitialized])

  return null
}

