  )

  if (user) {
    return <SignOut user={user} authProvider={authProvider} />
  } else {
    return <SignIn />
  }
}

'use client'

import type { Session } from '@/lib/session/types'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { redirectToSignOut } from '@/lib/session/redirect-to-sign-out'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import { useSetAtom, useAtomValue } from 'jotai'
import { sessionAtom } from '@/lib/atoms/session'
import { githubConnectionAtom } from '@/lib/atoms/github-connection'
import { GitHubIcon } from '@/components/icons/github-icon'
import { ApiKeysDialog } from '@/components/api-keys-dialog'
import { SandboxesDialog } from '@/components/sandboxes-dialog'
import { ThemeToggle } from '@/components/theme-toggle'
import { Key, Server } from 'lucide-react'
import { useState, useEffect, useCallback } from 'react'
import { getEnabledAuthProviders } from '@/lib/auth/providers'

interface RateLimitInfo {
  used: number
  total: number
  remaining: number
}

export function SignOut({ user, authProvider }: Pick<Session, 'user' | 'authProvider'>) {
  const router = useRouter()
  const setSession = useSetAtom(sessionAtom)
  const githubConnection = useAtomValue(githubConnectionAtom)
  const setGitHubConnection = useSetAtom(githubConnectionAtom)
  const [showApiKeysDialog, setShowApiKeysDialog] = useState(false)
  const [showSandboxesDialog, setShowSandboxesDialog] = useState(false)
  const [rateLimit, setRateLimit] = useState<RateLimitInfo | null>(null)

  // Check which auth providers are enabled
  const { github: hasGitHub } = getEnabledAuthProviders()

  const handleSignOut = async () => {
    await redirectToSignOut()
    toast.success('You have been logged out.')
    setSession({ user: undefined })
    router.refresh()
  }

  const handleGitHubDisconnect = async () => {
    try {
      const response = await fetch('/api/auth/github/disconnect', { method: 'POST' })
      if (response.ok) {
        // Immediately update the atom to reflect disconnected state
        setGitHubConnection({ connected: false })
        toast.success('GitHub disconnected')
        router.refresh()
      } else {
        toast.error('Failed to disconnect GitHub')
      }
    } catch (error) {
      console.error('Failed to disconnect GitHub:', error)
      toast.error('Failed to disconnect GitHub')
    }
  }

  // Fetch rate limit info on mount
  useEffect(() => {
    let mounted = true
    ;(async () => {
      try {
        const response = await fetch('/api/auth/rate-limit')
        if (response.ok && mounted) {
          const data = await response.json()
          setRateLimit({
            used: data.used,
            total: data.total,
            remaining: data.remaining,
          })
        }
      } catch (error) {
        console.error('Failed to fetch rate limit:', error)
      }
    })()
    return () => {
      mounted = false
    }
  }, [])

  const fetchRateLimit = useCallback(async () => {
    try {
      const response = await fetch('/api/auth/rate-limit')
      if (response.ok) {
        const data = await response.json()
        setRateLimit({
          used: data.used,
          total: data.total,
          remaining: data.remaining,
        })
      }
    } catch (error) {
      console.error('Failed to fetch rate limit:', error)
    }
  }, [])

  return (
    <DropdownMenu onOpenChange={(open) => open && fetchRateLimit()}>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          className="inline-flex items-center cursor-pointer focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary rounded-full"
        >
          <Avatar className="h-8 w-8">
            <AvatarImage src={user?.avatar ? `${user.avatar}&s=72` : undefined} alt={user.username} />
            <AvatarFallback>{user.username.slice(0, 2).toUpperCase()}</AvatarFallback>
          </Avatar>
        </button>
      </DropdownMenuTrigger>

      <DropdownMenuContent align="end" className="w-56">
        <div className="px-2 py-2">
          <div className="text-sm font-medium">
            <span>{user.name ?? user.username}</span>
          </div>
          {user.email && <div className="text-sm text-muted-foreground">{user.email}</div>}
          {rateLimit && (
            <div className="text-xs text-muted-foreground mt-1">
              {rateLimit.remaining}/{rateLimit.total} messages remaining today
            </div>
          )}
        </div>

        <DropdownMenuSeparator />

        <ThemeToggle />

        <DropdownMenuItem onClick={() => setShowApiKeysDialog(true)} className="cursor-pointer">
          <Key className="h-4 w-4 mr-2" />
          API Keys
        </DropdownMenuItem>

        <DropdownMenuItem onClick={() => setShowSandboxesDialog(true)} className="cursor-pointer">
          <Server className="h-4 w-4 mr-2" />
          Sandboxes
        </DropdownMenuItem>

        {/* Only show GitHub Connect/Disconnect for Vercel users when GitHub is enabled */}
        {authProvider === 'vercel' && hasGitHub && (
          <>
            {githubConnection.connected ? (
              <DropdownMenuItem onClick={handleGitHubDisconnect} className="cursor-pointer">
                <GitHubIcon className="h-4 w-4 mr-2" />
                Disconnect
              </DropdownMenuItem>
            ) : (
              <DropdownMenuItem
                onClick={() => (window.location.href = '/api/auth/github/signin')}
                className="cursor-pointer"
              >
                <GitHubIcon className="h-4 w-4 mr-2" />
                Connect
              </DropdownMenuItem>
            )}
          </>
        )}

        <DropdownMenuSeparator />

        <DropdownMenuItem onClick={handleSignOut} className="cursor-pointer">
          {authProvider === 'github' ? (
            <>
              <GitHubIcon className="h-4 w-4 mr-2" />
              Log Out
            </>
          ) : (
            <>
              <svg viewBox="0 0 76 65" className="h-3 w-3 mr-2" fill="currentColor">
                <path d="M37.5274 0L75.0548 65H0L37.5274 0Z" />
              </svg>
              Log Out
            </>
          )}
        </DropdownMenuItem>
      </DropdownMenuContent>

      <ApiKeysDialog open={showApiKeysDialog} onOpenChange={setShowApiKeysDialog} />
      <SandboxesDialog open={showSandboxesDialog} onOpenChange={setShowSandboxesDialog} />
    </DropdownMenu>
  )
}

/**
 * Get the list of enabled authentication providers from environment variables
 * Defaults to GitHub only if not specified
 */
export function getEnabledAuthProviders(): {
  github: boolean
  vercel: boolean
} {
  const providers = process.env.NEXT_PUBLIC_AUTH_PROVIDERS || 'github'
  const enabledProviders = providers.split(',').map((p) => p.trim().toLowerCase())

  return {
    github: enabledProviders.includes('github'),
    vercel: enabledProviders.includes('vercel'),
  }
}

'use client'

import { useState, useEffect } from 'react'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import { Eye, EyeOff } from 'lucide-react'

interface ApiKeysDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
}

type Provider = 'openai' | 'gemini' | 'cursor' | 'anthropic' | 'aigateway'

const PROVIDERS = [
  { id: 'aigateway' as Provider, name: 'AI Gateway', placeholder: 'gw_...' },
  { id: 'anthropic' as Provider, name: 'Anthropic', placeholder: 'sk-ant-...' },
  { id: 'openai' as Provider, name: 'OpenAI', placeholder: 'sk-...' },
  { id: 'gemini' as Provider, name: 'Gemini', placeholder: 'AIza...' },
  { id: 'cursor' as Provider, name: 'Cursor', placeholder: 'cur_...' },
]

export function ApiKeysDialog({ open, onOpenChange }: ApiKeysDialogProps) {
  const [apiKeys, setApiKeys] = useState<Record<Provider, string>>({
    openai: '',
    gemini: '',
    cursor: '',
    anthropic: '',
    aigateway: '',
  })
  const [savedKeys, setSavedKeys] = useState<Set<Provider>>(new Set())
  const [clearedKeys, setClearedKeys] = useState<Set<Provider>>(new Set())
  const [showKeys, setShowKeys] = useState<Record<Provider, boolean>>({
    openai: false,
    gemini: false,
    cursor: false,
    anthropic: false,
    aigateway: false,
  })
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (open) {
      fetchApiKeys()
    }
  }, [open])

  const fetchApiKeys = async () => {
    try {
      const response = await fetch('/api/api-keys')
      const data = await response.json()

      if (data.success) {
        const saved = new Set<Provider>()
        data.apiKeys.forEach((key: { provider: Provider }) => {
          saved.add(key.provider)
        })
        setSavedKeys(saved)
      }
    } catch (error) {
      console.error('Error fetching API keys:', error)
    }
  }

  const handleSave = async (provider: Provider) => {
    const key = apiKeys[provider]
    if (!key.trim()) {
      toast.error('Please enter an API key')
      return
    }

    setLoading(true)
    try {
      const response = await fetch('/api/api-keys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          provider,
          apiKey: key,
        }),
      })

      if (response.ok) {
        toast.success(`${PROVIDERS.find((p) => p.id === provider)?.name} API key saved`)
        setSavedKeys((prev) => new Set(prev).add(provider))
        setClearedKeys((prev) => {
          const newSet = new Set(prev)
          newSet.delete(provider)
          return newSet
        })
        setApiKeys((prev) => ({ ...prev, [provider]: '' }))
      } else {
        const error = await response.json()
        toast.error(error.error || 'Failed to save API key')
      }
    } catch (error) {
      console.error('Error saving API key:', error)
      toast.error('Failed to save API key')
    } finally {
      setLoading(false)
    }
  }

  const handleDelete = async (provider: Provider) => {
    setLoading(true)
    try {
      const response = await fetch(`/api/api-keys?provider=${provider}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        toast.success(`${PROVIDERS.find((p) => p.id === provider)?.name} API key deleted`)
        setSavedKeys((prev) => {
          const newSet = new Set(prev)
          newSet.delete(provider)
          return newSet
        })
        setClearedKeys((prev) => {
          const newSet = new Set(prev)
          newSet.delete(provider)
          return newSet
        })
      } else {
        const error = await response.json()
        toast.error(error.error || 'Failed to delete API key')
      }
    } catch (error) {
      console.error('Error deleting API key:', error)
      toast.error('Failed to delete API key')
    } finally {
      setLoading(false)
    }
  }

  const handleClear = async (provider: Provider) => {
    // Delete the key from the database
    setLoading(true)
    try {
      const response = await fetch(`/api/api-keys?provider=${provider}`, {
        method: 'DELETE',
      })

      if (response.ok) {
        toast.success(`${PROVIDERS.find((p) => p.id === provider)?.name} API key cleared`)
        setSavedKeys((prev) => {
          const newSet = new Set(prev)
          newSet.delete(provider)
          return newSet
        })
        setClearedKeys((prev) => {
          const newSet = new Set(prev)
          newSet.delete(provider)
          return newSet
        })
        setApiKeys((prev) => ({ ...prev, [provider]: '' }))
      } else {
        const error = await response.json()
        toast.error(error.error || 'Failed to clear API key')
      }
    } catch (error) {
      console.error('Error clearing API key:', error)
      toast.error('Failed to clear API key')
    } finally {
      setLoading(false)
    }
  }

  const toggleShowKey = (provider: Provider) => {
    setShowKeys((prev) => ({ ...prev, [provider]: !prev[provider] }))
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>API Keys</DialogTitle>
          <DialogDescription>
            Configure your own API keys. System defaults will be used if not provided.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-2">
          {PROVIDERS.map((provider) => {
            const hasSavedKey = savedKeys.has(provider.id)
            const isCleared = clearedKeys.has(provider.id)
            const showSaveButton = !hasSavedKey || isCleared
            const isInputDisabled = hasSavedKey && !isCleared

            return (
              <div key={provider.id} className="flex items-center gap-2">
                <Label htmlFor={provider.id} className="text-sm w-24 shrink-0">
                  {provider.name}
                </Label>
                <div className="relative flex-1">
                  <Input
                    id={provider.id}
                    type={showKeys[provider.id] ? 'text' : 'password'}
                    placeholder={hasSavedKey && !isCleared ? '••••••••••••••••' : provider.placeholder}
                    value={apiKeys[provider.id]}
                    onChange={(e) => setApiKeys((prev) => ({ ...prev, [provider.id]: e.target.value }))}
                    disabled={loading || isInputDisabled}
                    className="pr-9 h-8 text-sm"
                  />
                  <button
                    onClick={() => toggleShowKey(provider.id)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                    type="button"
                    disabled={loading || isInputDisabled}
                  >
                    {showKeys[provider.id] ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
                  </button>
                </div>
                {showSaveButton ? (
                  <Button
                    size="sm"
                    onClick={() => handleSave(provider.id)}
                    disabled={loading || !apiKeys[provider.id].trim()}
                    className="h-8 px-3 text-xs w-16"
                  >
                    Save
                  </Button>
                ) : (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleClear(provider.id)}
                    disabled={loading}
                    className="h-8 px-3 text-xs w-16"
                  >
                    Clear
                  </Button>
                )}
              </div>
            )
          })}
        </div>
      </DialogContent>
    </Dialog>
  )
}

